compute:
const cost = Number(itemCost) || 0;
const mk = (Number(markupPercent) || 0) / 100;
const qty = Number(quantity) || 1;
const price = cost * (1 + mk);
const unitProfit = price - cost;
const margin = price > 0 ? (unitProfit / price) * 100 : 0;
const totalProfit = unitProfit * qty;
return { margin, price, unitProfit, totalProfit };

